CREATE TABLE facility_tasks(id TEXT PRIMARY KEY,property_id INTEGER NOT NULL REFERENCES property(id),kind TEXT NOT NULL CHECK(kind IN ('water','technical')),title TEXT NOT NULL,location TEXT NOT NULL DEFAULT '',assigned TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL DEFAULT 'Normal',recurrence TEXT NOT NULL DEFAULT 'once',due TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,created TEXT NOT NULL,actor TEXT NOT NULL);
CREATE INDEX facility_tasks_property ON facility_tasks(property_id,kind,active,due);
CREATE TABLE facility_checks(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES facility_tasks(id),property_id INTEGER NOT NULL REFERENCES property(id),day TEXT NOT NULL,result TEXT NOT NULL,level INTEGER,notes TEXT NOT NULL DEFAULT '',created TEXT NOT NULL,actor TEXT NOT NULL);
CREATE INDEX facility_checks_task ON facility_checks(task_id,day,created);
CREATE TABLE notification_outbox(id TEXT PRIMARY KEY,property_id INTEGER NOT NULL REFERENCES property(id),event TEXT NOT NULL,message TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE notification_deliveries(event_id TEXT NOT NULL REFERENCES notification_outbox(id),channel TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',PRIMARY KEY(event_id,channel));
